begin;
create temp table qa_docs as select m.id mid,m.client_id cid,c.auth_user_id puid,cl.auth_user_id cuid,(select auth_user_id from public.admins limit 1) auid from public.missions m join public.convoyeurs c on c.id=m.convoyeur_id join public.clients cl on cl.id=m.client_id where m.reference_courte='HC-2026-0013';
grant select on qa_docs to authenticated;
select set_config('request.jwt.claim.sub',(select cuid::text from qa_docs),true);
set local role authenticated;
insert into storage.objects(bucket_id,name) select 'pieces-missions',cid::text||'/'||cuid::text||'/qa-rollback.pdf' from qa_docs;
insert into public.pieces_mission(client_id,mission_id,nom,chemin,auteur_role,partage_partenaire) select cid,mid,'QA rollback',cid::text||'/'||cuid::text||'/qa-rollback.pdf','FAUX ADMIN',true from qa_docs;
do $$ begin if not exists(select 1 from public.pieces_mission where nom='QA rollback' and auteur_role='Client' and not partage_partenaire) then raise exception 'Client insert ou normalisation cassée';end if;end $$;
select set_config('request.jwt.claim.sub',(select puid::text from qa_docs),true);
do $$ begin if exists(select 1 from public.pieces_mission where nom='QA rollback') then raise exception 'Partenaire voit un document non partagé';end if;if exists(select 1 from storage.objects where bucket_id='pieces-missions' and name like '%qa-rollback.pdf') then raise exception 'Fichier privé exposé';end if;end $$;
select set_config('request.jwt.claim.sub',(select auid::text from qa_docs),true);
update public.pieces_mission set partage_partenaire=true where nom='QA rollback';
select set_config('request.jwt.claim.sub',(select puid::text from qa_docs),true);
do $$ begin if not exists(select 1 from public.pieces_mission where nom='QA rollback') then raise exception 'Partage invisible';end if;if not exists(select 1 from storage.objects where bucket_id='pieces-missions' and name like '%qa-rollback.pdf') then raise exception 'Fichier partagé inaccessible';end if;end $$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
do $$ begin if exists(select 1 from public.pieces_mission where nom='QA rollback') then raise exception 'Document accessible à un tiers';end if;end $$;
reset role;
select 'PASS dépôt client, auteur réel, absence de partage automatique, visibilité après partage admin, stockage privé et tiers refusé' result;
rollback;
